import foodomicspy as fdef test_package_version():    assert f.__version__ == "0.1.0"def test_public_modules_available():    assert hasattr(f, "io")    assert hasattr(f, "preprocessing")    assert hasattr(f, "nmr")    assert hasattr(f, "chemometrics")    assert hasattr(f, "plotting")    assert hasattr(f, "utils")def test_plotting_functions_available():    assert callable(f.plotting.plot_y_distribution)    assert callable(f.plotting.plot_nmr_interactive)    assert callable(f.plotting.plot_ftir_interactive)    assert callable(f.plotting.plot_correlation_bubbles)    assert callable(f.plotting.plot_pls)    assert callable(f.plotting.save_figure)